"use client"

import * as React from "react"
import { useMorph } from "@/lib/sahajiv-motion/use-morph"
import { cva, type VariantProps } from "class-variance-authority"
import { cn } from "@/lib/utils"

const cardVariants = cva(
  "v-card relative content-start overflow-hidden rounded-[var(--r-card)] p-[var(--card-pad)] bg-[var(--card)] text-[color:var(--card-foreground)]",
  {
    variants: {
      variant: {
        default: "",
        pink: "-pink bg-[var(--v-pink)] text-[color:var(--v-on-accent)] [--wm:var(--v-pink-deep)] [--muted-foreground:var(--muted-foreground-ink)]",
        yellow: "-yellow bg-[var(--v-yellow)] text-[color:var(--v-on-accent)] [--wm:var(--v-yellow-deep)] [--muted-foreground:var(--muted-foreground-ink)]",
        olive: "-olive bg-[var(--v-olive)] text-[color:var(--v-on-accent)] [--wm:var(--v-olive-deep)] [--muted-foreground:var(--muted-foreground-ink)]",
        blue: "-blue bg-[var(--v-blue)] text-[color:var(--v-on-accent)] [--wm:var(--v-blue-deep)] [--muted-foreground:var(--muted-foreground-ink)]",
        ink: "-ink bg-[var(--v-ink)] text-[color:var(--v-on-ink)]",
        cream: "-cream bg-[var(--card-2)] [--muted-foreground:var(--muted-foreground-tinted)]",
        featured: "-featured bg-[var(--v-canvas)] [box-shadow:inset_0_0_0_var(--bw-featured)_var(--v-pink)]",
        panel: "-panel",
        lift: "-lift hover:[transform:translateY(-1px)] hover:[box-shadow:var(--shadow-lift)]",
      },
      size: { default: "", sm: "-sm rounded-[var(--r-card-sm)] p-[var(--s-4)]" },
      lift: { true: "-lift hover:[transform:translateY(-1px)] hover:[box-shadow:var(--shadow-lift)]", false: "" },
    },
    compoundVariants: [{ variant: "panel", className: "rounded-[var(--r-panel)]" }],
    defaultVariants: { variant: "default", size: "default", lift: false },
  },
)

type CardProps = React.ComponentProps<"div"> & VariantProps<typeof cardVariants>
function Card({ ref: externalRef, className, variant, size, lift, ...props }: CardProps) {
  const morphRef = useMorph<HTMLDivElement>("cards", externalRef)
  return <div ref={morphRef} data-slot="card" data-part="root" data-state="rest" className={cn(cardVariants({ variant, size, lift }), className)} {...props} />
}
function CardHeader({ className, ...props }: React.ComponentProps<"div">) {
  return <div data-slot="card-header" data-part="header" className={cn("v-card__head flex items-center justify-between gap-[var(--s-3)] mb-[var(--s-4)]", className)} {...props} />
}
function CardTitle({ className, ...props }: React.ComponentProps<"h3">) {
  return <h3 data-slot="card-title" data-part="title" className={cn("v-card__title text-[16px] font-semibold leading-[1.2] tracking-[-.012em]", className)} {...props} />
}
function CardContent({ className, ...props }: React.ComponentProps<"div">) {
  return <div data-slot="card-content" className={className} {...props} />
}
function CardDescription({ className, ...props }: React.ComponentProps<"p">) {
  return <p data-slot="card-description" className={cn("v-body-2", className)} {...props} />
}
function CardFooter({ className, ...props }: React.ComponentProps<"div">) {
  return <div data-slot="card-footer" className={className} {...props} />
}
function CardWatermark({ className, ...props }: React.ComponentProps<"span">) {
  return <span data-slot="card-watermark" data-part="watermark" aria-hidden="true" className={cn("v-wm v-shape", className)} {...props} />
}
export { Card, CardHeader, CardTitle, CardContent, CardDescription, CardFooter, CardWatermark, cardVariants }
export type { CardProps }

@layer sahajiv-states {
.v-card[data-slot] { transition: transform var(--t-micro) var(--enter), box-shadow var(--t-micro); }
.v-card[data-slot] > :not(.v-wm) { position: relative; z-index: 1; }
.v-card[data-slot] > .v-wm {
  position: absolute; right: -6%; top: -14%; width: 38%; max-width: 150px; height: auto;
  aspect-ratio: 1; color: var(--wm,var(--v-beige-2)); pointer-events: none; z-index: 0; opacity: .55;
}
.v-card[data-slot] > .v-wm.-bl { right: auto; left: -10%; top: auto; bottom: -20%; }
.v-card[data-slot] > .v-wm.-br { top: auto; bottom: -16%; }
.v-card[data-slot] > .v-wm.-tr-sm { width: 30%; right: 8%; top: 8%; }
.v-card[data-slot] > .v-body-2 + * { margin-top: 20px; }
/* The complete source cascade resets Stat control geometry (components-2.css). */
.v-card[data-slot] .v-stat[data-slot].-ul { border: 0; box-shadow: none; }
/* A nested card supplies its own secondary ink instead of inheriting its host's. */
.v-card[data-slot] { --card-secondary-ink: var(--v-text-2); }
.v-card[data-slot].-cream { --card-secondary-ink: var(--muted-foreground-tinted); }
:root[data-mode="dark"] .v-card[data-slot].-cream { --card-secondary-ink: var(--v-text-2); }
.v-card[data-slot]:is(.-pink,.-yellow,.-olive,.-blue) { --card-secondary-ink: var(--muted-foreground-ink); }
.v-card[data-slot].-ink { --card-secondary-ink: var(--v-on-ink); }
.v-card[data-slot] :is(.v-meta,.v-body-2,.v-caps,.v-stat span),
:root[data-mode="dark"] .v-card[data-slot] :is(.v-meta,.v-body-2,.v-caps,.v-stat span) { color: var(--card-secondary-ink); }

[data-slot=card-watermark]{display:inline-block;background:var(--c,currentColor);-webkit-mask:var(--m) center/contain no-repeat;mask:var(--m) center/contain no-repeat;flex:none}
[data-slot=card-watermark].-cross{--m:url("data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%270%200%20100%20100%27%3E%3Cpath%20d%3D%22M36%204H64Q68%204%2068%208V32H92Q96%2032%2096%2036V64Q96%2068%2092%2068H68V92Q68%2096%2064%2096H36Q32%2096%2032%2092V68H8Q4%2068%204%2064V36Q4%2032%208%2032H32V8Q32%204%2036%204Z%22%3E%3C%2Fpath%3E%3C%2Fsvg%3E");/* @kind other */}
[data-slot=card-watermark].-heart{--m:url("data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20viewBox%3D%270%200%20100%20100%27%3E%3Cpath%20d%3D%22M50%2090C22%2068%206%2052%206%2033A20%2020%200%200%201%2050%2021A20%2020%200%200%201%2094%2033C94%2052%2078%2068%2050%2090Z%22%3E%3C%2Fpath%3E%3C%2Fsvg%3E");/* @kind other */}

}
